namespace RunnersZ.Logic { public readonly struct DifficultyConfig { public readonly Difficulty Difficulty;public readonly int Enemies;public readonly float Interval;public readonly int Hints;public readonly bool ShowsShift; public DifficultyConfig(Difficulty d){Difficulty=d;Enemies=d==Difficulty.Easy?5:d==Difficulty.Normal?8:12;Interval=d==Difficulty.Easy?10f:d==Difficulty.Normal?7f:5f;Hints=d==Difficulty.Easy?3:d==Difficulty.Normal?2:1;ShowsShift=d==Difficulty.Easy;}}}